(function(root){
 'use strict';
 function timestamp(value){const m=String(value).trim().match(/^(?:(\d+):)?(\d{1,2})(?:\.(\d{1,3}))?$/);if(!m)return null;const seconds=Number(m[2]);if(m[1]&&seconds>=60)return null;return Number(m[1]||0)*60+seconds+Number('0.'+(m[3]||'0'))}
 function parse(text){const offset=Number(text.match(/\[offset:([+-]?\d+)\]/i)?.[1]||0)/1000;const lines=[];let timed=false;
  for(const row of text.replace(/\r/g,'').split('\n')){const times=[...row.matchAll(/\[(\d+:\d{1,2}(?:\.\d{1,3})?)\]/g)].map(m=>timestamp(m[1])).filter(t=>t!==null);let body=row.replace(/\[[^\]]*\]/g,'').trim();if(!body&&!times.length)continue;const words=[];for(const word of body.matchAll(/<(\d+:\d{1,2}(?:\.\d{1,3})?)>([^<]*)/g)){const time=timestamp(word[1]);if(time!==null)words.push({time:Math.max(0,time+offset),text:word[2]})}body=body.replace(/<\d+:\d{1,2}(?:\.\d{1,3})?>/g,'').trim();if(times.length){timed=true;for(const time of times)lines.push({time:Math.max(0,time+offset),text:body,words:words.map(w=>({...w,time:Math.max(0,w.time+time-times[0])}))})}else if(body)lines.push({time:null,text:body,words:[]})}
  if(timed)return {timed:true,lines:lines.filter(l=>l.time!==null).sort((a,b)=>a.time-b.time)};return {timed:false,lines};
 }
 function activeIndex(lines,time){let lo=0,hi=lines.length;while(lo<hi){const mid=(lo+hi)>>1;if(lines[mid].time<=time)lo=mid+1;else hi=mid}return lo-1}
 function format(time){time=Math.max(0,Number(time)||0);const cents=Math.round(time*100);return String(Math.floor(cents/6000)).padStart(2,'0')+':'+String(Math.floor(cents/100)%60).padStart(2,'0')+'.'+String(cents%100).padStart(2,'0')}
 function serialize(lines){return lines.map(l=>(l.time===null?'':'['+format(l.time)+'] ')+l.text).join('\n')}
 function appleURL(input){let url;try{url=new URL(input)}catch{throw Error('Paste a complete Apple Music link, starting with https://music.apple.com/.')}if(url.protocol!=='https:'||!['music.apple.com','embed.music.apple.com'].includes(url.hostname)||url.username||url.password)throw Error('Use a link from music.apple.com.');const parts=url.pathname.split('/').filter(Boolean);if(parts.length<3||!/^[a-z]{2}$/i.test(parts[0])||!['song','album','playlist'].includes(parts[1]))throw Error('Choose a song, album, or playlist link. Artist pages cannot play here.');if(!/^(?:\d+|pl\.[A-Za-z0-9._-]+)$/.test(parts.at(-1)))throw Error('This link is missing a valid song, album, or playlist ID.');const clean=new URL('https://music.apple.com'+url.pathname);if(url.searchParams.has('i')){const id=url.searchParams.get('i');if(!/^\d+$/.test(id))throw Error('The song ID in this link is invalid.');clean.searchParams.set('i',id)}const embed=new URL(clean.href);embed.hostname='embed.music.apple.com';embed.searchParams.set('theme','dark');return {url:clean.href,embed:embed.href,type:parts[1],title:decodeURIComponent(parts[2]||'Apple Music').replace(/-/g,' '),country:parts[0]}}
 const api={timestamp,parse,activeIndex,format,serialize,appleURL};root.LyricCore=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
